name: Repository Commands
on:
  issue_comment:
    types: [created]

jobs:
  commands:
    runs-on: ubuntu-latest
    steps:
      - name: Check for repository commands
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { issue: { number: issue_number }, comment } = context;
            const { body, user } = comment;

            // Only respond to comments on issues, not pull requests
            if (!context.payload.issue || !context.payload.issue.number) {
              return;
            }

            // Skip if the comment is from the bot itself
            if (user.login === 'github-actions[bot]') {
              return;
            }

            // Check for /makerelease command
            if (body.trim() === '/makerelease') {
              // Verify user has write permissions
              const { data: permission } = await github.rest.repos.getCollaboratorPermissionLevel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                username: user.login
              });

              if (permission.permission !== 'write' && permission.permission !== 'admin') {
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number,
                  body: `@${user.login} Sorry, you don't have permission to run this command.`
                });
                return;
              }

              // Create release
              try {
                const { data: releases } = await github.rest.repos.listReleases({
                  owner: context.repo.owner,
                  repo: context.repo.repo
                });

                const latestRelease = releases[0];
                const version = latestRelease ? 
                  latestRelease.tag_name.replace('v', '') : 
                  '1.0.0';

                const newVersion = version.split('.').map((part, index) => {
                  if (index === version.split('.').length - 1) {
                    return parseInt(part) + 1;
                  }
                  return part;
                }).join('.');

                const newTagName = `v${newVersion}`;

                await github.rest.repos.createRelease({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  tag_name: newTagName,
                  name: newTagName,
                  draft: true,
                  prerelease: false
                });

                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number,
                  body: `@${user.login} Created release ${newTagName}. Please review and publish when ready.`
                });
              } catch (error) {
                console.error(error);
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number,
                  body: `@${user.login} Failed to create release: ${error.message}`
                });
              }
            }
